CREATE OR REPLACE FUNCTION registry_context.evaluation_date()
              RETURNS date
              LANGUAGE sql
              STABLE
              SECURITY INVOKER
              AS $breg_function$
                  SELECT NULLIF(current_setting('registry.evaluation_date', true), '')::date
              $breg_function$;
CREATE TABLE registry_data."breg_e_asset_item_2815cb9d14108c83" (record_id uuid NOT NULL, record_revision bigint NOT NULL DEFAULT 1 CHECK (record_revision > 0), record_lifecycle text NOT NULL DEFAULT 'active' CHECK (record_lifecycle IN ('active', 'tombstoned')), created_at timestamptz NOT NULL DEFAULT transaction_timestamp(), updated_at timestamptz NOT NULL DEFAULT transaction_timestamp(), active_package_revision text NOT NULL DEFAULT NULLIF(current_setting('registry.active_package_revision', true), '') CHECK (active_package_revision <> ''), PRIMARY KEY (record_id), "breg_f_asset_item_asset_class_59b0ac5555eaf27f" text NOT NULL CHECK ("breg_f_asset_item_asset_class_59b0ac5555eaf27f" IN ('equipment', 'vehicle', 'furniture')), "breg_f_asset_item_asset_code_6c16fb1ab277d053" varchar(64) NOT NULL, "breg_f_asset_item_label_60d11cc69eac40cc" varchar(200) NOT NULL);
